    "inputs": {
      "script": "const body = $vars.getBellevueWeather1.output.body;\nconst tempF = body && body.current ? body.current.temperature_2m : null;\nconst unit = body && body.current_units ? body.current_units.temperature_2m : 'F';\nconst summaryText = `Current temperature in Bellevue, WA: ${tempF}${unit}`;\nreturn { temperature: tempF, summary: summaryText };"
